Create Procedure GuiasPen as SELECT WAREHOUSE_ID,NUMBER_DOCUMENT,DATE_DOCUMENT,CUSTOMER_NAME,TRANS_ID,DOC_ID_REF,NUM_ID_REF,STATUS_GUIA,CUSTOMER_ID,VAT_REGISTRATION,DOCUMENT_ID,CURRENCY_TYPE from [IVM].dbo.WAREHOUSE_TRANS WHERE DOCUMENT_ID = 'GS' AND (TRANS_ID = 'GV') AND (TYPE_GUIA = 'GV' ) AND STATUS_GUIA NOT IN ('A','F')  and CUSTOMER_ID>='100' and CUSTOMER_ID<='20552558902' and DATE_DOCUMENT>='01-10-2013' and DATE_DOCUMENT<='31-10-2013' order by DATE_DOCUMENT